CREATE DATABASE IF NOT EXISTS seckill_activity DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE seckill_activity;
CREATE TABLE IF NOT EXISTS seckill_activities(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(200) NOT NULL,description VARCHAR(500),preview_time DATETIME NOT NULL,start_time DATETIME NOT NULL,end_time DATETIME NOT NULL,status TINYINT NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_time(preview_time,start_time,end_time))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS seckill_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,activity_id BIGINT NOT NULL,product_id BIGINT NOT NULL,product_name VARCHAR(200) NOT NULL,product_title VARCHAR(200),product_images TEXT,original_price DECIMAL(10,2) NOT NULL,seckill_price DECIMAL(10,2) NOT NULL,stock INT NOT NULL,limit_per_user INT NOT NULL DEFAULT 1,status TINYINT NOT NULL DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_activity(activity_id),KEY idx_product(product_id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
